typedef int8_t data_t;
typedef int8_t weight_t;
typedef int32_t acc_t;

inline data_t rescale_and_relu(acc_t acc) {
_ssdm_InlineSelf(0, "");
 acc_t rounded = (acc + 32) >> 6;
    if (rounded <= 0) return 0;
    if (rounded > 127) return 127;
    return (data_t)rounded;
}

inline data_t rescale_linear(acc_t acc) {
_ssdm_InlineSelf(0, "");
 acc_t rounded = (acc + 32) >> 6;
    if (rounded > 127) return 127;
    if (rounded < -128) return -128;
    return (data_t)rounded;
}

inline acc_t simd_mac16(const data_t act[16], const weight_t w[16]) {_ssdm_SpecArrayDimSize(act, 16);_ssdm_SpecArrayDimSize(w, 16);
_ssdm_InlineSelf(0, "");
 acc_t prod[16];
_ssdm_SpecArrayPartition( prod, 1, "COMPLETE", 0, "");

 for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 prod[k] = (acc_t)act[k] * (acc_t)w[k];
    }

    acc_t stage1[8];
_ssdm_SpecArrayPartition( stage1, 1, "COMPLETE", 0, "");
 for (int k = 0; k < 8; ++k) {
_ssdm_Unroll(0,0,0, "");
 stage1[k] = prod[2*k] + prod[2*k + 1];
    }

    acc_t stage2[4];
_ssdm_SpecArrayPartition( stage2, 1, "COMPLETE", 0, "");
 for (int k = 0; k < 4; ++k) {
_ssdm_Unroll(0,0,0, "");
 stage2[k] = stage1[2*k] + stage1[2*k + 1];
    }

    acc_t stage3[2];
_ssdm_SpecArrayPartition( stage3, 1, "COMPLETE", 0, "");
 stage3[0] = stage2[0] + stage2[1];
    stage3[1] = stage2[2] + stage2[3];

    return stage3[0] + stage3[1];
}

void mlp_accel_8b(const data_t in_vec[784], data_t out_vec[10]) {_ssdm_SpecArrayDimSize(in_vec, 784);_ssdm_SpecArrayDimSize(out_vec, 10);
_ssdm_op_SpecInterface(0, "s_axilite", 0, 0, "", 0, 0, "CTRL_BUS", "", "", 0, 0, 0, 0, "", "");
_ssdm_op_SpecInterface(in_vec, "s_axilite", 0, 0, "", 0, 0, "CTRL_BUS", "", "", 0, 0, 0, 0, "", "");
_ssdm_op_SpecInterface(out_vec, "s_axilite", 0, 0, "", 0, 0, "CTRL_BUS", "", "", 0, 0, 0, 0, "", "");

 data_t input_buf[49][16];
_ssdm_SpecArrayPartition( input_buf, 2, "COMPLETE", 0, "");

 data_t ping_buf[8][16];
_ssdm_SpecArrayPartition( ping_buf, 2, "COMPLETE", 0, "");

 data_t pong_buf[4][16];
_ssdm_SpecArrayPartition( pong_buf, 2, "COMPLETE", 0, "");

 data_t out_buf[10];
_ssdm_SpecArrayPartition( out_buf, 1, "COMPLETE", 0, "");

_ssdm_SpecArrayPartition( &weights_l1_8b, 3, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( &weights_l2_8b, 3, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( &weights_l3_8b, 3, "COMPLETE", 0, "");


 for (int b = 0; b < 49; ++b) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 input_buf[b][k] = in_vec[b * 16 + k];
        }
    }


    L1_LOOP: for (int n = 0; n < 128; ++n) {
        acc_t acc = 0;
        L1_BLOCKS_LOOP: for (int b = 0; b < 49; ++b) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 data_t act_chunk[16];
            weight_t w_chunk[16];
_ssdm_SpecArrayPartition( act_chunk, 1, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( w_chunk, 1, "COMPLETE", 0, "");
 for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 act_chunk[k] = input_buf[b][k];
                w_chunk[k] = weights_l1_8b[n][b][k];
            }
            acc += simd_mac16(act_chunk, w_chunk);
        }
        ping_buf[n / 16][n % 16] = rescale_and_relu(acc);
    }


    L2_LOOP: for (int n = 0; n < 64; ++n) {
        acc_t acc = 0;
        L2_BLOCKS_LOOP: for (int b = 0; b < 8; ++b) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 data_t act_chunk[16];
            weight_t w_chunk[16];
_ssdm_SpecArrayPartition( act_chunk, 1, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( w_chunk, 1, "COMPLETE", 0, "");
 for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 act_chunk[k] = ping_buf[b][k];
                w_chunk[k] = weights_l2_8b[n][b][k];
            }
            acc += simd_mac16(act_chunk, w_chunk);
        }
        pong_buf[n / 16][n % 16] = rescale_and_relu(acc);
    }


    L3_LOOP: for (int n = 0; n < 10; ++n) {
        acc_t acc = 0;
        L3_BLOCKS_LOOP: for (int b = 0; b < 4; ++b) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 data_t act_chunk[16];
            weight_t w_chunk[16];
_ssdm_SpecArrayPartition( act_chunk, 1, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( w_chunk, 1, "COMPLETE", 0, "");
 for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 act_chunk[k] = pong_buf[b][k];
                w_chunk[k] = weights_l3_8b[n][b][k];
            }
            acc += simd_mac16(act_chunk, w_chunk);
        }
        out_buf[n] = rescale_linear(acc);
    }


    for (int i = 0; i < 10; ++i) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 out_vec[i] = out_buf[i];
    }
}
